  if (!health.install?.compiledRecordRefs)
    reasonCodes.add("cli_install_not_ready");
  const sortedReasonCodes = [...reasonCodes].sort();
  if (sortedReasonCodes.length > 0 || !health.install || !health.probes || !config2.x402ProbeReportRef || !health.install.compiledRecordRefs || !health.install.selectedPaymentRequirementDigest) {
    return {
      record: null,
      reasonCodes: sortedReasonCodes,
      nextAction: "fix_install"
    };
  }
  const recordedAt = new Date().toISOString();
  const gatewayReadinessRef = localGatewayReadinessRecordRef(config2);
  const rawSiblingProofRefs = rawSiblingProofRefsForProbes(health.probes);
