  const readinessStatus = trustedReady ? "trusted_gateway_ready" : input.install?.installStatus === "ready_to_install" && input.probes?.passed === true && !input.reasonCodes.includes("cli_gateway_posture_stale") ? "local_posture_evidence_present" : "not_ready";
