    rawPrivateKeyEnvStatus: "absent",
    directCoreClientSigningStatus: "blocked",
    paidFetchClientStatus: "blocked",
    paidAxiosClientStatus: "blocked",
    rawPaymentSignatureHeaderStatus: "blocked",
    siblingX402WrapperStatus: "blocked",
